ALTER TABLE devices
  ADD COLUMN build text,
  ADD COLUMN last_synced_at timestamptz;

-- Every device seen since the 4.18 release reported its build in the sync header.
UPDATE devices SET build = coalesce(last_header ->> 'build', 'unknown') WHERE build IS NULL;

ALTER TABLE devices ALTER COLUMN build SET NOT NULL;
ALTER TABLE devices DROP COLUMN legacy_client;
